function products(){let list=store.products.filter(p=>(category==='all'||p.category===category)&&localized(p,'name').toLowerCase().includes(search.toLowerCase()));if(sort!=='default')list.sort((a,b)=>sort==='low'?a.price-b.price:b.price-a.price);document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.cat===category));document.querySelectorAll('.products').forEach(grid=>{grid.innerHTML=list.length?list.map(p=>`<article class="product"><button class="product-image${p.locked?' locked':''}" data-detail="${esc(p.id)}">${p.image?`<img src="${esc(p.image)}" loading="lazy" alt="${esc(localized(p,'name'))}">`:`<span class="img-placeholder" aria-hidden="true">${esc((localized(p,'name')||'M').slice(0,1).toUpperCase())}</span>`}${p.badge?`<span class="badge">${esc(p.badge==='NEW'?t('new'):p.badge==='BESTSELLER'?t('best'):p.badge==='EDITORS’ PICK'?t('pick'):p.badge)}</span>`:''}<span class="quick-view">${t('detail')} ↗</span></button><div class="product-meta"><span>${esc(catName(store.categories.find(c=>c.id===p.category)||{name:''}))}</span><span>${p.stock?t('stock'):t('out')}</span></div><h3><button data-detail="${esc(p.id)}">${esc(localized(p,'name'))}</button></h3><div class="product-bottom"><div class="price">${Number(p.compareAt||0)>Number(p.price)?`<s>${money(p.compareAt)}</s><strong class="sale">${money(p.price)}</strong><span class="off">-${Math.round((1-p.price/p.compareAt)*100)}%</span>`:`<strong>${money(p.price)}</strong>`}</div><button class="add" data-add="${esc(p.id)}" ${p.stock?'':'disabled'} aria-label="${t('add')}">＋</button></div></article>`).join(''):`<p class="empty">${t('empty')}</p>`;grid.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));grid.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(b.dataset.add));});}
