function detail(id){const p=store.products.find(p=>p.id===id);if(p.locked)return vipNotice();track('product',id);const gallery=[p.image,...(Array.isArray(p.images)?p.images:[])].filter(Boolean);document.title=localized(p,'name')+' — '+store.brand;show(`<div class="detail"><div class="detail-media">${gallery.length?`<button class="detail-main" data-zoom aria-label="${t('zoom')}"><img id="detail-image" src="${esc(gallery[0])}" alt="${esc(localized(p,'name'))}"><span class="zoom-hint">${t('zoom')} ＋</span></button>`:`<div class="detail-main img-placeholder">${esc((localized(p,'name')||'M').slice(0,1).toUpperCase())}</div>`}${gallery.length>1?`<div class="thumbs">${gallery.map((u,i)=>`<button data-thumb="${i}" class="${i===0?'active':''}" aria-label="${i+1}"><img src="${esc(u)}" alt="" loading="lazy"></button>`).join('')}</div>`:''}</div><div><p class="eyebrow">MERIDIAN SELECTION</p><h2>${esc(localized(p,'name'))}</h2><h3 class="detail-price">${Number(p.compareAt||0)>Number(p.price)?`<s>${money(p.compareAt)}</s> ${money(p.price)} <span class="off">-${Math.round((1-p.price/p.compareAt)*100)}%</span>`:money(p.price)}</h3><p class="description">${esc(localized(p,'description'))}</p>${p.specs&&Object.values(p.specs).some(Boolean)?`<table class="specs"><tbody>${Object.entries(p.specs).filter(([,v])=>v&&String(v).trim()).map(([k,v])=>`<tr><th>${esc(specLabel(k))}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table>`:''}<p class="stock-line">${t('stock')}: ${p.stock} · USD</p><div class="detail-actions"><button class="button" id="detail-buy" ${p.stock?'':'disabled'}>${p.stock?t('buyNow'):t('out')}</button><button class="button outline" id="detail-add" ${p.stock?'':'disabled'}>${p.stock?t('add'):t('out')}</button></div><p class="muted small">${t('guestNote')}</p></div></div>`);let current=0;const main=$('#detail-image');document.querySelectorAll('[data-thumb]').forEach(b=>b.onclick=()=>{current=+b.dataset.thumb;main.src=gallery[current];document.querySelectorAll('[data-thumb]').forEach(x=>x.classList.toggle('active',x===b));});$('[data-zoom]').onclick=()=>openLightbox(gallery,current);$('#detail-add').onclick=()=>add(id);$('#detail-buy').onclick=()=>{buyNow=[{id,quantity:1}];checkout();};}

async function authScreen(mode='login'){
 const title=mode==='login'?t('loginTitle'):t('registerTitle');
 show(`<div class="auth-panel"><p class="eyebrow">${t('account')}</p><h2>${title}</h2><form id="auth-form"><label>${t('email')}<input name="email" type="email" required maxlength="200" autocomplete="email"></label>${mode==='register'?`<label>${t('name')}<input name="name" maxlength="80" autocomplete="name"></label>`:''}<label>${t('password')}<input name="password" type="password" required minlength="8" maxlength="200" autocomplete="${mode==='login'?'current-password':'new-password'}"></label><button class="button full">${mode==='login'?t('login'):t('register')}</button><p class="form-error" role="alert"></p></form><p class="auth-switch"><button type="button" id="auth-switch">${mode==='login'?t('needAccount'):t('haveAccount')}</button></p></div>`);
 $('#auth-switch').onclick=()=>authScreen(mode==='login'?'register':'login');
 $('#auth-form').onsubmit=async e=>{
  e.preventDefault();
  const btn=e.target.querySelector('button');btn.disabled=true;
  try{
   const payload=Object.fromEntries(new FormData(e.target));
   await api('/api/auth/'+(mode==='login'?'login':'register'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
   store=await api('/api/store');render();modal.close();
   toast(mode==='login'?t('welcomeBack'):t('welcome'));
   if(location.pathname.replace(/\/+$/,'')==='/account'){renderAccountPage();}
  }catch(err){
   const box=$('.form-error');if(box)box.textContent=err.message;btn.disabled=false;
  }
 };
}
function shipFor(subtotalDollars){
 const cfg=Object.assign({mode:'auto',percent:8,flat:12,freeOver:150},store.shipping||{});
 const cents=Math.round(subtotalDollars*100);
 const flat=Number(cfg.flat||0)/100, freeOver=Number(cfg.freeOver||0)/100, pct=Number(cfg.percent||0);
 if(cfg.mode==='free')return 0;
 if(cfg.mode==='percent'){if(freeOver>0&&subtotalDollars>=freeOver)return 0;return Math.round(subtotalDollars*pct)/100;}
 if(cfg.mode==='flat'){if(freeOver>0&&subtotalDollars>=freeOver)return 0;return flat;}
 return freeOver>0&&subtotalDollars>=freeOver?0:flat;
}
